import json

def extract_constraints(tree):
    if not tree:
        return set()
    if tree[0] == 'single':
        return {tree[1]}
    result = set()
    for child in tree[1]:
        result |= extract_constraints(child)
    return result

# Check a few domains - find negative tasks with specific constraints
for domain in ['healthcare', 'bank', 'hotel', 'library']:
    with open(f'data/{domain}_tasks.json') as f:
        tasks = json.load(f)
    print(f'=== {domain} ===')
    for action, task_list in tasks.items():
        for i, t in enumerate(task_list):
            if not t['action_should_succeed']:
                cons = extract_constraints(t['constraints'])
                if 'claim_within_limits' in cons or 'maximum_deposit_limit' in cons or 'within_max_room_changes' in cons or 'within_borrow_limit' in cons:
                    print(f'  {action}[{i}]: {sorted(cons)[:5]}')

    print()
